@import "@fontsource-variable/newsreader/opsz.css";
@import "@fontsource-variable/instrument-sans";

/* Light (faithful): paper and ink. White page, a warm oat surface for windows and cards, ink
   #292929 for text and dark pills, warm greys, olive hairlines. Dark olive for the main
   Download pill, lime for the chat band and the New badge, a pastel rainbow (chart-1…5) only for
   text shimmers. */
:root {
  --background: #ffffff;
  --foreground: #292929;
  --card: #f7f7f2;
  --card-foreground: #292929;
  --popover: #ffffff;
  --popover-foreground: #292929;
  --primary: #5b6f00;
  --primary-foreground: #fcfcf8;
  --secondary: #eaebe5;
  --secondary-foreground: #292929;
  --muted: #f2f2ec;
  --muted-foreground: #72726e;
  --accent: #efefe7;
  --accent-foreground: #292929;
  --destructive: #e95d3d;
  --destructive-foreground: #fcfcf8;
  --border: #47432a33;
  --input: #47432a33;
  --ring: #b2c24899;
  --highlight: #b2c248;
  --highlight-foreground: #292929;
  --glow: #d1e043;
  --chart-1: #febe29;
  --chart-2: #ff91e0;
  --chart-3: #cebef8;
  --chart-4: #d2e4f8;
  --chart-5: #d1e043;
  --sidebar: #f7f7f2;
  --sidebar-foreground: #292929;
  --sidebar-primary: #5b6f00;
  --sidebar-primary-foreground: #fcfcf8;
  --sidebar-accent: #efefe7;
  --sidebar-accent-foreground: #292929;
  --sidebar-border: #47432a33;
  --sidebar-ring: #b2c24899;

  --typeface-body: "Instrument Sans Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Newsreader Variable", ui-serif, Georgia, serif;
  --typeface-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 0.5rem;
  --page-width: 75rem;
  --page-gutter: 1rem;
  --section-y: 5.5rem;
}

/* Dark: the charcoal bands of the original (logo wall, testimonials) as a whole page. Oat-white
   ink, a lifted charcoal for cards, lime as the brand colour with ink text on it, the olive kept
   for the lime band so its text stays light. */
.dark {
  --background: #292929;
  --foreground: #fcfcf8;
  --card: #363635;
  --card-foreground: #fcfcf8;
  --popover: #363635;
  --popover-foreground: #fcfcf8;
  --primary: #b2c248;
  --primary-foreground: #292929;
  --secondary: #484844;
  --secondary-foreground: #fcfcf8;
  --muted: #333332;
  --muted-foreground: #9e9e99;
  --accent: #3d3d3b;
  --accent-foreground: #fcfcf8;
  --destructive: #e95d3d;
  --destructive-foreground: #fcfcf8;
  --border: #ffffff33;
  --input: #ffffff26;
  --ring: #b2c24899;
  --highlight: #788c15;
  --highlight-foreground: #fcfcf8;
  --glow: #b2c248;
  --chart-1: #febe29;
  --chart-2: #ff91e0;
  --chart-3: #cebef8;
  --chart-4: #d2e4f8;
  --chart-5: #d1e043;
  --sidebar: #333332;
  --sidebar-foreground: #fcfcf8;
  --sidebar-primary: #b2c248;
  --sidebar-primary-foreground: #292929;
  --sidebar-accent: #3d3d3b;
  --sidebar-accent-foreground: #fcfcf8;
  --sidebar-border: #ffffff33;
  --sidebar-ring: #b2c24899;
}
